    );
    expect(
      dispatcher.handleKeyDown(key("F6", { shiftKey: true })).commandId,
    ).toBe("nav.previousRegion");
    expect(calls).toEqual(["focusNextRegion", "focusPreviousRegion"]);
  });
});

